import {CROPS,ensureCrops,cropStage,cropProgress,plantSeeds,waterCrop,harvestCrop,fertiliseCrop} from './crops.js?v=simulation15';
export function installCropUI({state,save,modal,toast,perform,station,refresh}){
 window.openCropBeds=()=>{ensureCrops(state);modal('<span class="service-tag">FOUR INDEPENDENT BEDS</span><h2>Your kitchen garden</h2><p>Your home garden is available in every farm role. Choose a crop for each bed. Water once; growth then continues in real time, including while the game is closed. Next day advances 24 hours of crop growth. Animal fertiliser shortens an active crop cycle by 20%.</p>'+state.cropBeds.map((b,id)=>{const c=CROPS[b?.type||'maize'],stage=cropStage(state,id),p=cropProgress(state,id);return '<article class="county-card"><h3>Bed '+(id+1)+' · '+(b?c.name:'Empty')+'</h3>'+(b?'<p>'+({planted:'Needs '+c.water+' water',growing:Math.floor(p*100)+'% grown · '+Math.max(0,Math.ceil((b.hours||c.hours)*(1-p)))+' hours remaining',ready:'Ready for harvest'}[stage])+'</p><progress max="1" value="'+p+'"></progress><div class="choice"><button onclick="bedAction('+id+',\'water\')" '+(stage!=='planted'?'disabled':'')+'>Water · '+c.water+'</button><button onclick="bedAction('+id+',\'fertilise\')" '+(b.fertilised||stage==='ready'?'disabled':'')+'>Compost · 2 fertiliser</button><button onclick="bedAction('+id+',\'harvest\')" '+(stage!=='ready'?'disabled':'')+'>Harvest '+c.yield+' '+c.name+'</button></div>':'<div class="choice">'+Object.entries(CROPS).map(([type,c])=>'<button onclick="bedAction('+id+',\'plant\',\''+type+'\')">'+c.name+' · '+c.seeds+' seeds / '+c.hours+'h</button>').join('')+'</div>')+'</article>';}).join('')+'<button onclick="openMarket(\'seeds\')">Buy seeds in Supplies / Exchange</button><p>Each crop stays within its own bed. Maize feeds the mill; other crops can be traded on the exchange.</p>');};
 window.bedAction=(id,action,type)=>{const spec={plant:[()=>plantSeeds(state,id,type),'Plant bed '+(id+1),'plant'],water:[()=>waterCrop(state,id),'Water bed '+(id+1),'water'],harvest:[()=>harvestCrop(state,id),'Harvest bed '+(id+1),'harvest'],fertilise:[()=>fertiliseCrop(state,id),'Compost bed '+(id+1),'plant']}[action];if(!spec)return;perform(station(id),()=>{try{spec[0]();save();refresh();toast(spec[1]+' completed.');}catch(e){toast(e.message);}},spec[1],spec[2]);};
}
